from pathlib import Path
import json

additions={
'03-001':'''Например, летописное сообщение о приглашении князя в Новгород нужно читать иначе, чем запись о переходе владимирского стола к наследнику. В первом случае вопрос состоит в условиях соглашения с городом, во втором — в признании династического права и поддержке местных сил. Оба события происходят внутри связанного культурного пространства, но показывают разные способы распределения власти. При сравнении следует отдельно выписать участников решения: князей, городские общины, бояр, церковных руководителей. Если источник называет только князя, это ещё не доказывает отсутствия остальных участников: летописный рассказ мог сосредоточиться на династии и опустить переговоры.''',
'03-002':'''Полезно сравнить, что сообщает каждый вид памятника о строительстве во Владимире. Сам храм показывает материалы, технику и художественную программу; летопись может связывать заказ с именем князя и его благочестием. Однако ни один из этих источников отдельно не объясняет, кто предоставил труд и как распределялись расходы. Здесь возникает предметный вопрос о ресурсах княжеского двора и отношениях с местными группами. Известие о конфликте вокруг Андрея Боголюбского также требует различать заговор ближайшего окружения и настроение всей земли. Рассказ о заговорщиках позволяет изучать двор, но не заменяет отсутствующего свидетельства каждого горожанина.''',
'03-003':'''Для проверки полезны две группы источников: записи о политических столкновениях и договорные ограничения князя. Первая показывает, что происходило в конфликтной ситуации; вторая — какие правила стороны хотели закрепить. Если князю запрещали определённое действие, запрет нельзя автоматически считать доказательством его постоянного соблюдения. Напротив, само повторение условия могло быть связано с опасением злоупотреблений. Нужно также различать участие человека в городской толпе, возможность выступить на вече и устойчивое влияние семьи на должности. Все три явления относятся к политической жизни, но требуют разных доказательств. Поэтому слово «республика» полезно только вместе с объяснением её общественных ограничений.''',
'03-004':'''На примере Галицко-Волынской земли особенно заметно различие между дипломатической программой и доступными средствами. Даниил мог искать внешнюю поддержку, однако обещание помощи и прибытие войска — разные события. Проверяя сообщение о переговорах, нужно установить, кто обещал содействие, какие обязательства ожидал взамен и последовало ли исполнение. Энциклопедическое изложение объединяет длительную борьбу Романовичей в связный рассказ; оно не позволяет считать все решения частью неизменного плана. Отдельно исследуются отношения с городами и боярством: внешнее признание князя не уничтожало внутренние конфликты. Так объясняется, почему королевский титул мог сосуществовать с тяжёлыми ограничениями реальной самостоятельности.''',
'03-005':'''Практическое сравнение можно построить вокруг одного вопроса: от кого правитель получал необходимые ресурсы. Новгородская торговая грамота раскрывает платежи, перевозку и охрану приезжих купцов; княжеская летопись может подробнее говорить о походах и наследовании. Неравенство сведений ещё не означает, что один регион жил только торговлей, а другой — исключительно земледелием. Сначала следует учесть назначение документов и различия их сохранности. Затем сопоставить одинаковые признаки: положение землевладельцев, доступ к торговым сборам, способы привлечения военной силы. Только после этого можно объяснять, почему сходные доходы превращались в разные политические возможности для князя, бояр и общины.''',
'03-006':'''Учебные материалы о монголах показывают значение военной организации, но военная иерархия не описывает всех отношений внутри державы. Удержание земледельческого города требовало доходов, посредников и сведений о населении; непрерывное разорение могло уменьшать будущие поступления. Поэтому исследователь различает насилие при завоевании и последующие способы извлечения ресурсов, не оправдывая одно существованием другого. После разделения политического центра улусы сохраняли собственные интересы и могли конфликтовать между собой. На карте одинаковое происхождение династий не должно превращаться в доказательство единого управления всеми территориями. Проверять нужно конкретный период, получателя платежей и инстанцию, которая подтверждала права местных правителей.''',
'03-007':'''Сопоставление общемирового обзора завоеваний с русской летописью меняет масштаб наблюдения. Первый помогает увидеть одновременные кампании и решения наследников Чингисхана; вторая показывает последствия конкретного нападения для города и княжеской семьи. Их различия не следует устранять: они отвечают на разные вопросы. Рассказ о внезапности удара ещё не означает отсутствия предварительной разведки, а перечисление разрушенных городов не восстанавливает точной дороги между ними. Для анализа остановки похода необходимы отдельные данные о снабжении, состоянии войска и политических известиях. Причину прекращения наступления нельзя без дополнительной проверки переносить на каждую армию и каждый участок огромного фронта.''',
'03-008':'''В опубликованной выборке Новгородской летописи осада Рязани и рассказ о Владимире объединены общим годовым заголовком. При составлении современной хронологии нужно учитывать устройство летописного года, а не механически переносить заголовок на все зимние события. Другая трудность — язык повествования: обозначение противника и объяснение катастрофы передают позицию христианского книжника. Они важны для истории переживания нашествия, но не дают точного числа нападавших. Сопоставление городов требует археологических датировок каждого памятника. Отдельный след пожара нельзя превращать в карту общего опустошения, пока не установлены его время, масштаб и связь с другими находками.''',
'03-009':'''Для хозяйственных последствий полезно разделить несколько показателей: восстановление ремесла, объём обмена, плотность поселений и поступление дани. Они могли изменяться неодновременно. Даже возвращение привозных вещей не доказывает восстановления прежней торговой сети: посредники и направления обмена могли стать другими. Летописец чаще замечал бедствие или необычный конфликт, чем постепенное возобновление работы мастерских. Поэтому молчание текста о восстановлении не равнозначно отсутствию хозяйственной жизни. Вместе с тем появление новых связей не отменяет ущерба от гибели людей и разрушения городов. Обоснованная оценка удерживает оба наблюдения и не подменяет сравнение регионов единым показателем «упадка» или «прогресса».''',
'03-010':'''Разделите зависимость на право, доход и принуждение. Ханское подтверждение княжеских прав относится к первому уровню; дань — ко второму; поход или угроза наказания — к третьему. Совпадение этих механизмов усиливало верховенство Орды, но каждый из них оставлял местным князьям пространство переговоров и соперничества. Известие о поездке князя к хану поэтому нужно читать вместе с последующими решениями: какую поддержку он получил и кого это ослабило. Напротив, сохранение собственного суда показывает продолжение местных институтов, но не доказывает свободы от внешних обязательств. Для разных десятилетий соотношение этих уровней могло быть неодинаковым.''',
'03-011':'''Сопоставляя летописное известие и житийное повествование, сначала определите задачу каждого текста. Летопись могла сохранять память о столкновениях князя с новгородцами; житие выстраивало образ достойного христианского правителя и отбирало соответствующие эпизоды. Несовпадение акцентов не позволяет просто объявить один рассказ полностью ложным, а другой беспристрастным. Нужно установить время записи, зависимость текстов и круг сведений автора. Особенно осторожно следует обращаться с прямой речью: литературно оформленные слова не равнозначны стенограмме переговоров. Оценка отношений Александра с Ордой требует учитывать и военное неравенство, и внутреннюю борьбу за власть, сохраняя различие между объяснением решения и его нравственным оправданием.''',
'03-012':'''Торговая грамота 1229 года позволяет поставить конкретные вопросы о границе: кто обеспечивал безопасность купца, где возникал спор о платеже и кто имел право его разрешать. Такие нормы показывают переговорную инфраструктуру контактов, а не только движение товаров. Одновременно они свидетельствуют о наличии рисков, иначе их закрепление не требовалось бы. В отношении западных соседей важно различать интересы купцов, епископов, орденских руководителей и князей. Их действия не обязательно совпадали даже при общей вере или языке. Военный конфликт на одном направлении поэтому нужно рассматривать отдельно от договорных отношений с другими участниками балтийского обмена.''',
'03-013':'''Язык канцелярии, вера населения и происхождение правящей династии — разные признаки. Документ, составленный в привычной письменной традиции, мог служить новой верховной власти и закреплять новые обязательства. Для понимания литовского расширения нужно спрашивать, кто сохранял владения, кому приносили службу и как разрешались конфликты с местной знатью. Сохранение прежних норм могло быть способом сделать переход власти менее затратным, а не доказательством отсутствия перемен. Нельзя также переносить опыт одной земли на все владения Великого княжества. Энциклопедическая общая характеристика полезна как начало сравнения, но конкретный случай требует своей хронологии, документов и анализа отношений местных групп с династией.''',
'03-014':'''Сравнение Москвы и Твери следует строить не по их будущей судьбе, а по доступным современникам возможностям. Значение имели династические притязания, союзы, доходы, церковные связи и отношения с Ордой. Удачное приобретение одного князя ещё не доказывает устойчивого преимущества его наследников: раздел владений или смена ханской поддержки могли изменить положение. Источники победившего центра способны подробнее сохранять собственные права и слабее представлять доводы соперника. Поэтому отсутствие подробного тверского рассказа нельзя принимать за отсутствие политической программы. Историческая альтернатива становится убедительной тогда, когда показаны реальные действия и ресурсы, а не только выражено сожаление о несостоявшемся исходе.''',
'03-015':'''Для реконструкции Калки нужно отдельно установить последовательность сближения войск, решения отдельных князей и действия половецких союзников. Рассказ, объясняющий поражение раздором, может сохранять важное наблюдение, но одновременно придавать событию назидательный смысл. Его нельзя превращать в точную схему приказов без дополнительных свидетельств. Общий обзор монгольской тактики помогает поставить вопросы о разведке, манёвре и преследовании, однако не доказывает применение каждого известного приёма именно в этом бою. Даже определение места сражения требует специального исследования. Поэтому учебная карта может честно показывать общий регион, сохраняя неопределённость вместо произвольного размещения отдельных полков и переправ.''',
'03-016':'''У Старой Рязани важно не спутать археологическое городище с современным областным центром. Совпадение названия не гарантирует совпадения места, поэтому сначала проверяется география памятника. Далее сопоставляются датировка разрушения и последовательность летописного рассказа. Для Владимира вопрос иной: как сообщение о судьбе княжеской семьи соотносится с описанием осады и последующего преследования князя Юрия. Текст может объединять одновременно происходившие действия в последовательное повествование. Это удобно читателю, но не даёт готового поминутного плана операции. Надёжная реконструкция обозначает, какие города и события установлены, а где остаются пробелы в движении войск и датировке отдельных эпизодов.''',
'03-017':'''У ярлыка следует проверить адресата, перечисленные права и условия их действия. Привилегия церковной организации не обязательно описывает обязанности всех остальных жителей; подтверждение княжеского положения не гарантирует отсутствия соперника. Нормативная грамота говорит о признанном порядке, тогда как летописное известие о конфликте помогает увидеть его исполнение или нарушение. Для изучения дани нужны ещё сведения о сборщиках, распределении платежей и последствиях отказа. Даже если два документа используют похожую формулу, их практическое значение могло различаться из-за времени выдачи и положения адресатов. Так исследование документа переходит от общего слова «зависимость» к конкретным отношениям между ханом, князем, церковью и населением.''',
'03-018':'''Торговую грамоту 1229 года полезно читать как попытку распределить расходы и ответственность. Охрана купца, перевозка и порядок платежей показывают, что обмен требовал местных посредников и согласованных правил. Однако предписание ещё не доказывает, что конфликтов больше не возникало. Нужно искать сведения о спорах, задержках и новых соглашениях. Редактор публикации специально предупреждает против переноса зрелой организации Ганзы на все ранние связи немецких купцов. Поэтому следует различать присутствие торговцев из определённых городов и согласованное действие их объединения. Это различие помогает объяснить, как постепенно складывались общие привилегии и почему торговая сеть не была единым государством.''',
'03-019':'''Предположим, исследователь связывает усиление князя с ордынским опытом управления. Проверка должна включать не только сходство полномочий, но и сравнение домонгольских форм власти, местных конфликтов и хронологии изменений. Возможны несколько совместимых механизмов: заимствование отдельного приёма, использование ханской поддержки в межкняжеской борьбе и развитие собственных институтов в новых условиях. Каждый механизм оставляет разные следы в источниках. Учебный план лекции о монголах и Руси помогает сформулировать такие вопросы, но не заменяет исследования документа. Поэтому отсутствие единого ответа на общий спор не мешает получать обоснованные частные выводы о конкретном платеже, привилегии или политическом решении.'''
}
folder=Path('src/content/lessons')
# Preserve the original snapshot and avoid appending the same additions twice.
if Path('tasks/001-russian-history-course/deep03-before.json').exists():
    all_applied=all(json.loads((folder/(key+'.json')).read_text())['deep']['text'].endswith(addition) for key,addition in additions.items())
    if all_applied:
        print('All 19 additions are already present; original snapshot preserved.')
        raise SystemExit(0)
    raise SystemExit('An original snapshot already exists; inspect partial changes before running again.')
before={}
counts={}
for key,addition in additions.items():
 p=folder/(key+'.json');lesson=json.loads(p.read_text());before[key]={'deep':lesson['deep'].copy(),'status':lesson['status']}
 old=lesson['deep']['text']
 lesson['deep']['text']=old+'\n\n'+addition
 assert lesson['deep']['text'].startswith(old+'\n\n')
 count=len(lesson['deep']['text'].split());assert count>=100,(key,count)
 assert lesson['status']==before[key]['status']
 original=json.loads(p.read_text());original['deep']['text']=lesson['deep']['text'];assert original==lesson
 p.write_text(json.dumps(lesson,ensure_ascii=False,indent=2)+'\n');counts[key]=count
out=Path('tasks/001-russian-history-course')
(out/'deep03-before.json').write_text(json.dumps(before,ensure_ascii=False,indent=2)+'\n')
(out/'deep03-word-counts.json').write_text(json.dumps(counts,ensure_ascii=False,indent=2)+'\n')
print('Expanded',len(counts),'lessons; words:',min(counts.values()),'to',max(counts.values()),'; all original deep prefixes and statuses preserved.')
